<?php
 namespace QQWorld\ConfigurableProduct\Controller\Adminhtml\Product\Initialization\Helper\Plugin; class UpdateConfigurations { protected $productRepository; protected $request; protected $variationHandler; private $keysPost = [ 'status', 'sku', 'name', 'price', 'configurable_attribute', 'weight', 'media_gallery', 'swatch_image', 'small_image', 'thumbnail', 'image', ]; public function __construct( \QQWorld\Framework\App\RequestInterface $request, \QQWorld\Catalog\Api\ProductRepositoryInterface $productRepository, \QQWorld\ConfigurableProduct\Model\Product\VariationHandler $variationHandler ) { $this->request = $request; $this->productRepository = $productRepository; $this->variationHandler = $variationHandler; } public function afterInitialize( \QQWorld\Catalog\Controller\Adminhtml\Product\Initialization\Helper $subject, \QQWorld\Catalog\Model\Product $configurableProduct ) { $configurations = $this->getConfigurations(); $configurations = $this->variationHandler->duplicateImagesForVariations($configurations); if (count($configurations)) { foreach ($configurations as $productId => $productData) { $product = $this->productRepository->getById($productId, false, $this->request->getParam('store', 0)); $productData = $this->variationHandler->processMediaGallery($product, $productData); $product->addData($productData); if ($product->hasDataChanges()) { $product->save(); } } } return $configurableProduct; } protected function getConfigurations() { $result = []; $configurableMatrix = $this->request->getParam('configurable-matrix-serialized', "[]"); if (isset($configurableMatrix) && $configurableMatrix != "") { $configurableMatrix = json_decode($configurableMatrix, true); foreach ($configurableMatrix as $item) { if (empty($item['was_changed'])) { continue; } else { unset($item['was_changed']); } if (!$item['newProduct']) { $result[$item['id']] = $this->mapData($item); if (isset($item['qty'])) { $result[$item['id']]['quantity_and_stock_status']['qty'] = $item['qty']; } } } } return $result; } private function mapData(array $item) { $result = []; foreach ($this->keysPost as $key) { if (isset($item[$key])) { $result[$key] = $item[$key]; } } return $result; } } 